package com.lianpayhub.service.website;

import com.lianpayhub.common.error.*;
import com.lianpayhub.domain.website.*;
import com.lianpayhub.repository.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class WebsiteContentService {
    private final WebsiteProductRepository products; private final WebsiteArticleRepository articles; private final WebsiteLeadRepository leads; private final WebsiteSiteSettingsRepository settings;
    public WebsiteContentService(WebsiteProductRepository products, WebsiteArticleRepository articles, WebsiteLeadRepository leads, WebsiteSiteSettingsRepository settings){this.products=products;this.articles=articles;this.leads=leads;this.settings=settings;}
    @Transactional(readOnly=true) public List<WebsiteProduct> adminProducts(){return products.findAllByOrderBySortOrderAscIdAsc();}
    @Transactional(readOnly=true) public List<WebsiteArticle> adminArticles(){return articles.findAllByOrderByUpdatedAtDesc();}
    @Transactional(readOnly=true) public List<WebsiteLead> adminLeads(){return leads.findAllByOrderByCreatedAtDesc();}
    @Transactional public WebsiteProduct createProduct(String slug,String appId,String name,String tagline,String summary,String accent,String cover,String download,String purchase,String content,Integer sort,String previewProject,String previewVolume,String previewChapter,String previewExcerpt,String previewInsight,String previewChapterTwo,String previewExcerptTwo,String previewChapterThree,String previewExcerptThree,String previewBody,String previewDraft){ requireNewProductSlug(slug); WebsiteProduct p=new WebsiteProduct(slug,appId,name,tagline,summary,accent,cover,download,purchase,content,sort);p.updatePreview(previewProject,previewVolume,previewChapter,previewExcerpt,previewInsight);p.updatePreviewDetails(previewChapterTwo,previewExcerptTwo,previewChapterThree,previewExcerptThree,previewBody,previewDraft);return products.save(p); }
    @Transactional public WebsiteProduct updateProduct(Long id,String appId,String name,String tagline,String summary,String accent,String cover,String download,String purchase,String content,Integer sort,String previewProject,String previewVolume,String previewChapter,String previewExcerpt,String previewInsight,String previewChapterTwo,String previewExcerptTwo,String previewChapterThree,String previewExcerptThree,String previewBody,String previewDraft){ WebsiteProduct p=product(id);p.update(appId,name,tagline,summary,accent,cover,download,purchase,content,sort);p.updatePreview(previewProject,previewVolume,previewChapter,previewExcerpt,previewInsight);p.updatePreviewDetails(previewChapterTwo,previewExcerptTwo,previewChapterThree,previewExcerptThree,previewBody,previewDraft);return products.save(p);}
    @Transactional public WebsiteProduct productStatus(Long id,ContentStatus status){WebsiteProduct p=product(id);p.changeStatus(status);return products.save(p);}
    @Transactional public void deleteProduct(Long id){products.delete(product(id));}
    @Transactional public WebsiteArticle createArticle(String slug,String category,String title,String excerpt,String cover,String content,String seoTitle,String seoDescription){requireNewArticleSlug(slug);return articles.save(new WebsiteArticle(slug,category,title,excerpt,cover,content,seoTitle,seoDescription));}
    @Transactional public WebsiteArticle updateArticle(Long id,String category,String title,String excerpt,String cover,String content,String seoTitle,String seoDescription){WebsiteArticle a=article(id);a.update(category,title,excerpt,cover,content,seoTitle,seoDescription);return articles.save(a);}
    @Transactional public WebsiteArticle articleStatus(Long id,ContentStatus status){WebsiteArticle a=article(id);a.changeStatus(status);return articles.save(a);}
    @Transactional public void deleteArticle(Long id){articles.delete(article(id));}
    @Transactional public WebsiteLead createLead(String name,String contact,String subject,String message){return leads.save(new WebsiteLead(name.trim(),contact.trim(),subject,message.trim()));}
    @Transactional public WebsiteLead leadStatus(Long id,String status){WebsiteLead l=leads.findById(id).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"线索不存在")); if(!Arrays.asList("NEW","PROCESSING","CLOSED").contains(status))throw new BusinessException(ErrorCode.BAD_REQUEST,"线索状态不合法");l.changeStatus(status);return leads.save(l);}
    @Transactional(readOnly=true) public List<WebsiteProduct> publicProducts(){return products.findByStatusOrderBySortOrderAscIdAsc(ContentStatus.PUBLISHED);}
    @Transactional(readOnly=true) public WebsiteProduct publicProduct(String slug){WebsiteProduct p=products.findBySlug(slug).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"产品不存在"));if(p.getStatus()!=ContentStatus.PUBLISHED)throw new BusinessException(ErrorCode.NOT_FOUND,"产品不存在");return p;}
    @Transactional(readOnly=true) public List<WebsiteArticle> publicArticles(String category){return category==null||category.trim().isEmpty()?articles.findByStatusOrderByPublishedAtDesc(ContentStatus.PUBLISHED):articles.findByCategoryAndStatusOrderByPublishedAtDesc(category,ContentStatus.PUBLISHED);}
    @Transactional(readOnly=true) public WebsiteArticle publicArticle(String slug){WebsiteArticle a=articles.findBySlug(slug).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"文章不存在"));if(a.getStatus()!=ContentStatus.PUBLISHED)throw new BusinessException(ErrorCode.NOT_FOUND,"文章不存在");return a;}
    @Transactional(readOnly=true) public WebsiteSiteSettings siteSettings(){return settings.findById(1L).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"站点设置不存在"));}
    @Transactional public WebsiteSiteSettings updateSiteSettings(WebsiteSiteSettings input){WebsiteSiteSettings target=settings.findById(1L).orElseGet(()->new WebsiteSiteSettings(1L));target.update(input.getName(),input.getEnglishName(),input.getHeroEyebrow(),input.getHeroTitle(),input.getHeroAccentTitle(),input.getHeroDescription(),input.getProductsHeading(),input.getProductsIntro(),input.getSystemHeading(),input.getSystemIntro(),input.getJournalHeading(),input.getCompanyHeading(),input.getCompanyDescription(),input.getContactHeading(),input.getContactDescription(),input.getEmail(),input.getProductCountLabel(),input.getYearsLabel(),input.getFeaturedProductSlug(),input.getHeroLocation(),input.getProductCountDescription(),input.getYearsDescription(),input.getSystemCtaLabel(),input.getSystemCoreEyebrow(),input.getSystemCoreTitle(),input.getSystemCoreMeta(),input.getSystemNodeOneTitle(),input.getSystemNodeOneMeta(),input.getSystemNodeTwoTitle(),input.getSystemNodeTwoMeta(),input.getSystemNodeThreeTitle(),input.getSystemNodeThreeMeta(),input.getPrincipleOneTitle(),input.getPrincipleOneDescription(),input.getPrincipleTwoTitle(),input.getPrincipleTwoDescription(),input.getPrincipleThreeTitle(),input.getPrincipleThreeDescription(),input.getContactEyebrow(),input.getFooterCopyright(),input.getIcpNumber());return settings.save(target);}
    private WebsiteProduct product(Long id){return products.findById(id).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"产品不存在"));} private WebsiteArticle article(Long id){return articles.findById(id).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"文章不存在"));}
    private void requireNewProductSlug(String slug){if(products.existsBySlug(slug))throw new BusinessException(ErrorCode.CONFLICT,"产品 slug 已存在");} private void requireNewArticleSlug(String slug){if(articles.existsBySlug(slug))throw new BusinessException(ErrorCode.CONFLICT,"文章 slug 已存在");}
}
